/* From Uiverse.io by Yaya12085 - Tags: card, paper, realistic */
.__UIV_SCOPE__ .page {
  position: relative;
  box-sizing: border-box;
  max-width: 300px;
  font-family: cursive;
  font-size: 20px;
  border-radius: 10px;
  background: #fff;
  background-image: linear-gradient(#f5f5f0 1.1rem, #ccc 1.2rem);
  background-size: 100% 1.2rem;
  line-height: 1.2rem;
  padding: 1.4rem 0.5rem 0.3rem 4.5rem;
}

.__UIV_SCOPE__ .page::before,
.__UIV_SCOPE__ .page::after {
  position: absolute;
  content: "";
  bottom: 10px;
  width: 40%;
  height: 10px;
  box-shadow: 0 5px 14px rgba(0, 0, 0, 0.7);
  z-index: -1;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .page::before {
  left: 15px;
  transform: skew(-5deg) rotate(-5deg);
}

.__UIV_SCOPE__ .page::after {
  right: 15px;
  transform: skew(5deg) rotate(5deg);
}

.__UIV_SCOPE__ .page:hover::before,
.__UIV_SCOPE__ .page:hover::after {
  box-shadow: 0 2px 14px rgba(0, 0, 0, 0.4);
}

.__UIV_SCOPE__ .margin {
  position: absolute;
  border-left: 1px solid #d88;
  height: 100%;
  left: 3.3rem;
  top: 0;
}

.__UIV_SCOPE__ .page p {
  margin: 0;
  text-indent: 1rem;
  padding-bottom: 1.2rem;
  color: black;
  line-height: 20px;
}
